      desc: "Route Health Injection (RHI) functionality of the NetSaler appliance for advertising the route of the VIP address associated with the virtual server. When Vserver RHI Level (RHI) parameter is set to VSVR_CNTRLD, the following are different RHI behaviors for the VIP address on the basis of RHIstate (RHI STATE) settings on the virtual servers associated with the VIP address:\n* If you set RHI STATE to PASSIVE on all virtual servers, the NetScaler ADC always advertises the route for the VIP address.\n* If you set RHI STATE to ACTIVE on all virtual servers, the NetScaler ADC advertises the route for the VIP address if at least one of the associated virtual servers is in UP state.\n* If you set RHI STATE to ACTIVE on some and PASSIVE on others, the NetScaler ADC advertises the route for the VIP address if at least one of the associated virtual servers, whose RHI STATE set to ACTIVE, is in UP state.",
    },
    new_service_request_rate: {
      type: "Optional[Variant[Integer, Pattern[/\\A\\d+\\z/]]]",
      desc: "Number of requests, or percentage of the load on existing services, by which to increase the load on a new service at each interval in slow-start mode. A non-zero value indicates that slow-start is applicable. A zero value indicates that the global RR startup parameter is applied. Changing the value to zero will cause services currently in slow start to take the full traffic as determined by the LB method. Subsequently, any new services added will use the global RR factor.",
    },
    new_service_request_unit: {
      type: "Optional[String]",
      desc: "Units in which to increment load at each interval in slow-start mode.\nPossible values = PER_SECOND, PERCENT",
    },
    new_service_request_increment_interval: {
      type: "Optional[Variant[Integer, Pattern[/\\A\\d+\\z/]]]",
      desc: "Interval, in seconds, between successive increments in the load on a new service or a service whose state has just changed from DOWN to UP. A value of 0 (zero) specifies manual slow start.\nMaximum value: 3600",
    },
    min_autoscale_members: {
      type: "Optional[Variant[Integer, Pattern[/\\A\\d+\\z/]]]",
      desc: "Minimum number of members expected to be present when vserver is used in Autoscale.\nMaximum value: 5000",
    },
    max_autoscale_members: {
      type: "Optional[Variant[Integer, Pattern[/\\A\\d+\\z/]]]",
      desc: "Maximum number of members expected to be present when vserver is used in Autoscale.\nMaximum value: 5000",
    },
    persist_avp_no: {
      type: "Optional[Variant[String, Integer, Array[Variant[String, Integer]]]]",
      desc: "Persist AVP number for Diameter Persistency.\nIn case this AVP is not defined in Base RFC 3588 and it is nested inside a Grouped AVP,\ndefine a sequence of AVP numbers (max 3) in order of parent to child. So say persist AVP number X\nis nested inside AVP Y which is nested in Z, then define the list as Z Y X\nMinimum value: 1",
    },
    skip_persistency: {
      type: "Optional[String]",
      desc: "This argument decides the behavior incase the service which is selected from an existing persistence session has reached threshold. Valid options: Bypass, ReLb, None.",
    },
    traffic_domain: {
      type: "Optional[Variant[Integer, Pattern[/\\A\\d+\\z/]]]",
      desc: "Integer value that uniquely identifies the traffic domain in which you want to configure the entity. If you do not specify an ID, the entity becomes part of the default traffic domain, which has an ID of 0.\nMinimum value: 0\nMaximum value: 4094",
      behaviour: :init_only,
    },
    authentication_profile_name: {
      type: "Optional[String]",
      desc: "Name of the authentication profile to be used when authentication is turned on.",
    },
    macmode_retain_vlan: {
      type: "Optional[Variant[Boolean, Enum['true', 'TRUE', 'yes', 'YES', 'enabled', 'ENABLED', 'on', 'ON', 'false', 'FALSE', 'no', 'NO', 'disabled', 'DISABLED', 'off', 'OFF']]]",
      desc: "This option is used to retain vlan information of incoming packet when macmode is enabled",
    },
    database_specific_lb: {
      type: "Optional[Variant[Boolean, Enum['true', 'TRUE', 'yes', 'YES', 'enabled', 'ENABLED', 'on', 'ON', 'false', 'FALSE', 'no', 'NO', 'disabled', 'DISABLED', 'off', 'OFF']]]",
      desc: "Enable database specific load balancing for MySQL and MSSQL service types.",
    },
    dns64: {
      type: "Optional[Variant[Boolean, Enum['true', 'TRUE', 'yes', 'YES', 'enabled', 'ENABLED', 'on', 'ON', 'false', 'FALSE', 'no', 'NO', 'disabled', 'DISABLED', 'off', 'OFF']]]",
      desc: "This argument is for enabling/disabling the dns64 on lbvserver",
    },
    bypass_aaaa: {
      type: "Optional[Variant[Boolean, Enum['true', 'TRUE', 'yes', 'YES', 'enabled', 'ENABLED', 'on', 'ON', 'false', 'FALSE', 'no', 'NO', 'disabled', 'DISABLED', 'off', 'OFF']]]",
      desc: "If this option is enabled while resolving DNS64 query AAAA queries are not sent to back end dns server",
    },
    recursion_available: {
      type: "Optional[Variant[Boolean, Enum['true', 'TRUE', 'yes', 'YES', 'enabled', 'ENABLED', 'on', 'ON', 'false', 'FALSE', 'no', 'NO', 'disabled', 'DISABLED', 'off', 'OFF']]]",
      desc: "When set to YES, this option causes the DNS replies from this vserver to have the RA bit turned on. Typically one would set this option to YES, when the vserver is load balancing a set of DNS servers thatsupport recursive queries.",
    },
    process_local: {
      type: "Optional[Variant[Boolean, Enum['true', 'TRUE', 'yes', 'YES', 'enabled', 'ENABLED', 'on', 'ON', 'false', 'FALSE', 'no', 'NO', 'disabled', 'DISABLED', 'off', 'OFF']]]",
      desc: "By turning on this option packets destined to a vserver in a cluster will not under go any steering. Turn this option for single packet request response mode or when the upstream device is performing a proper RSS for connection based distribution.",
    },
  },
)

# The transport caches the NITRO listings per device; no Resource API get cache
if Puppet::Type.type(:netscaler_lbvserver).respond_to?(:rsapi_provider_get_cache)
  Puppet::Type.type(:netscaler_lbvserver).define_singleton_method(:rsapi_provider_get_cache) { Puppet::ResourceApi::ProviderGetCache.new }
end
